```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

contract MultiSigWallet is Ownable, ReentrancyGuard {
    address[] public owners;
    uint256 public requiredConfirmations;

    struct Transaction {
        address to;
        uint256 value;
        bytes data;
        bool executed;
        uint256 confirmations;
    }

    mapping(uint256 => Transaction) public transactions;
    uint256 public transactionCount;

    event Deposit(address indexed sender, uint256 amount);
    event Withdrawal(address indexed to, uint256 amount);
    event ConfirmTransaction(uint256 indexed txIndex);
    event ExecuteTransaction(uint256 indexed txIndex);

    constructor(address[] memory _owners, uint256 _requiredConfirmations) {
        require(_owners.length > 0, "Owners required");
        require(
            _requiredConfirmations > 0 && _requiredConfirmations <= _owners.length,
            "Invalid number of required confirmations"
        );

        owners = _owners;
        requiredConfirmations = _requiredConfirmations;
    }

    modifier onlyOwner() {
        require(isOwner(msg.sender), "Not an owner");
        _;
    }

    function isOwner(address _address) public view returns (bool) {
        for (uint256 i = 0; i < owners.length; i++) {
            if (owners[i] == _address) {
                return true;
            }
        }
        return false;
    }

    function deposit() external payable onlyOwner {
        emit Deposit(msg.sender, msg.value);
    }

    function withdraw(uint256 amount, bytes memory data) external onlyOwner {
        require(msg.value >= amount, "Insufficient balance");
        require(!transactions[transactionCount].executed, "Transaction already executed");

        transactions[transactionCount] = Transaction({
            to: address(0),
            value: amount,
            data: data,
            executed: false,
            confirmations: 0
        });

        (bool success, ) = payable(msg.sender).call{value: amount}("");
        require(success, "Failed to withdraw");

        emit Withdrawal(msg.sender, amount);
    }

    function confirmTransaction(uint256 txIndex) external onlyOwner {
        require(!transactions[txIndex].executed, "Transaction already executed");
        require(!isConfirmed(txIndex), "Transaction already confirmed");

        transactions[txIndex].confirmations += 1;

        if (transactions[txIndex].confirmations >= requiredConfirmations) {
            executeTransaction(txIndex);
        }

        emit ConfirmTransaction(txIndex);
    }

    function executeTransaction(uint256 txIndex) internal {
        require(!transactions[txIndex].executed, "Transaction already executed");
        require(transactions[txIndex].confirmations >= requiredConfirmations, "Not enough confirmations");

        transactions[txIndex].executed = true;

        (bool success, ) = transactions[txIndex].to.call{value: transactions[txIndex].value, gas: tx.gasLimit}(
            transactions[txIndex].data
        );

        require(success, "Failed to execute transaction");

        emit ExecuteTransaction(txIndex);
    }

    function isConfirmed(uint256 txIndex) public view returns (bool) {
        return transactions[txIndex].confirmations >= requiredConfirmations;
    }

    function getTransactionCount() public view returns (uint256) {
        return transactionCount;
    }

    function getOwners() public view returns (address[] memory) {
        return owners;
    }

    function getRequiredConfirmations() public view returns (uint256) {
        return requiredConfirmations;
    }
}

